<template>
  <section class="ai-ball-showcase sf-ui" :data-reduce-motion="reduceMotion?'true':'false'">
    <header><h2>AI Ball 通用动效</h2><p>保留球体、色团与两只眼睛。状态由场景驱动，没有虚构生成进度。</p></header>
    <div class="ai-showcase-controls"><sf-switch v-model="fullPreview" label="完整动效预览" description="仅此 Demo 覆盖系统减少动态设置，也用于实际首页。"/><sf-switch v-model="reduceMotion" label="减少 AI 动态效果"/><button type="button" @click="blink">Preview blink</button><label for="ai-look">视线</label><select id="ai-look" v-model="gaze"><option value="auto">随场景</option><option value="center">正前方</option><option value="left">向左</option><option value="right">向右</option><option value="up">向上</option><option value="down">向下</option></select></div>
    <sf-segmented-control v-model="state" :items="states" label="AI activity"/>
    <div class="ai-ball-stage"><sf-ai-ball :state="state" :size="168" :gaze="gaze" :reduce-motion="reduceMotion" :blink-token="blinkToken"/><p aria-live="polite">{{ descriptions[state] }}</p></div>
    <section class="ai-reference-strip" aria-label="原稿姿态对照"><h3>原稿姿态对照</h3><p>核对五官位置与侧上方朝向。当前实现沿用已调整的通透玻璃与浅色色团。</p><article v-for="pose in referencePoses" :key="pose.gaze"><h4>{{ pose.label }}</h4><div class="ai-reference-images"><figure><img :src="pose.image" :alt="pose.label+' Figma 原稿'" width="56" height="56"><figcaption>Figma 原稿</figcaption></figure><figure><sf-ai-ball state="idle" :gaze="pose.gaze" :size="56" reduce-motion/><figcaption>当前组件</figcaption></figure></div></article></section>
    <div class="ai-states-grid"><article v-for="item in states" :key="item.value"><sf-ai-ball :state="item.value" :size="64" :reduce-motion="reduceMotion"/><div><h3>{{ item.label }}</h3><p>{{ descriptions[item.value] }}</p></div></article></div>
    <div class="ai-scenes-grid">
      <article class="ai-scene"><h3>问卷收集场景</h3><p class="ai-review-note">本地动效场景，生成过程为模拟，可测试取消和失败。</p><div class="ai-question-heading"><sf-ai-ball :state="questionState" :size="72" gaze="left" :reduce-motion="reduceMotion"/><div><p class="ai-step">{{ phase==='collecting'?'Step '+(questionIndex+1)+' of '+questions.length:phase==='complete'?'Preferences collected':'AI Coach' }}</p><h4>{{ phase==='collecting'?currentQuestion.title:phase==='thinking'?'Thinking about your preferences…':phase==='error'?'Let’s try again':'You’re ready to get started' }}</h4></div></div>
        <fieldset v-if="phase==='collecting'" class="ai-question-options"><legend class="sf-visually-hidden">{{ currentQuestion.title }}</legend><sf-choice v-for="option in currentQuestion.options" :key="option" v-model="answers[currentQuestion.id]" :label="option" :option="option" type="radio" :name="currentQuestion.id"/></fieldset>
        <p v-else-if="phase==='error'" class="ai-scene-copy" role="alert">Your answers are still here. Retry when you’re ready.</p><p v-else-if="phase==='complete'" class="ai-scene-copy">{{ answers.goal }} · {{ answers.time }} · {{ answers.experience }}</p>
        <sf-button v-if="phase==='collecting'" :disabled="!answers[currentQuestion.id]" @click="next">{{ questionIndex===questions.length-1?'Finish questionnaire':'Continue' }}</sf-button><sf-button v-if="phase==='error'" @click="generate">Retry</sf-button><sf-button v-if="phase==='thinking'" appearance="glass" @click="cancel">Cancel generation</sf-button><sf-button v-if="phase==='complete'" appearance="glass" @click="reset">Start again</sf-button><sf-switch v-model="simulateFailure" label="模拟生成失败"/>
      </article>
      <article class="ai-scene"><h3>首页待命场景</h3><p class="ai-review-note">复用 AI Coach 入口，保持位置和点击区域稳定。</p><div class="ai-home-preview"><sf-header title="Today" :back="false"/><sf-card title="Quick Start"><p class="ai-scene-copy">Morning Mobility<br>15 min · Free</p><sf-button @click="homeHint='Training action emitted'">Start Now</sf-button></sf-card><sf-card title="My Progress"><p class="ai-scene-copy">Your activities stay in view.</p></sf-card><button type="button" class="ai-home-entry" aria-label="Open AI Coach" @click="homeHint='AI Coach entry opened'"><sf-ai-ball state="idle" :size="64" decorative :reduce-motion="reduceMotion"/></button><p class="ai-home-hint" role="status">{{ homeHint }}</p></div></article>
    </div>
    <p class="ai-review-note">实际接入时，提交后进入 thinking；只有内容返回后才进入 responding 或 success，失败进入 error。减少动态效果时保留静态形态和状态文字。</p>
  </section>
</template>
<script>
import {SfAiBall,SfSegmentedControl,SfSwitch,SfChoice,SfButton,SfHeader,SfCard} from '@/design-system'
import {aiMotionPolicy,chooseDemoAiMotion} from '@/demo/ai-motion'
const descriptions={idle:'放松正视，偶尔看向侧上方；转头舒缓，眼睛和色团跟随同一个头部朝向。',listening:'面向输入区域，轻微确认，保留用户正在填写的内容。',thinking:'头部轻微变化，等待真实结果，不显示虚构百分比。',responding:'内容已返回，形象朝向输出内容。',success:'短眨一次后稳定，不自动切换业务状态。',error:'停止循环，保留输入，通过文字表达重试路径。'}
const referencePoses=[{gaze:'center',label:'正视 · 04',image:'/assets/figma/ai-ball-references/neutral-04.png'},{gaze:'left',label:'左上侧脸 · 01',image:'/assets/figma/ai-ball-references/left-up-01.png'},{gaze:'right',label:'右上侧脸 · 07',image:'/assets/figma/ai-ball-references/right-up-07.png'}]
export default {
  name:'AiBallShowcase', components:{SfAiBall,SfSegmentedControl,SfSwitch,SfChoice,SfButton,SfHeader,SfCard},
  data(){return {state:'idle',gaze:'auto',reduceMotion:false,blinkToken:0,descriptions,states:[{value:'idle',label:'待命'},{value:'listening',label:'收集信息'},{value:'thinking',label:'思考生成'},{value:'responding',label:'输出内容'},{value:'success',label:'完成'},{value:'error',label:'失败'}],phase:'collecting',questionIndex:0,answers:{goal:'',time:'',experience:''},simulateFailure:false,homeHint:'',generationVersion:0,questions:[{id:'goal',title:'What would you like to work on?',options:['Feel stronger','Build healthy habits','Improve endurance']},{id:'time',title:'How much time fits your day?',options:['10–15 minutes','20–30 minutes','More than 30 minutes']},{id:'experience',title:'How do you describe your experience?',options:['Just getting started','Some experience','Train regularly']}]}},
  computed:{
    referencePoses(){return referencePoses},
    fullPreview:{get(){return aiMotionPolicy.value==='full'},set(value){chooseDemoAiMotion(value?'full':'system')}},
    currentQuestion(){return this.questions[this.questionIndex]},
    questionState(){return this.phase==='collecting'?'listening':this.phase==='thinking'?'thinking':this.phase==='complete'?'success':'error'}
  },
  beforeDestroy(){this.cancelTimer()},
  methods:{
    blink(){this.blinkToken++},
    next(){if(!this.answers[this.currentQuestion.id])return;if(this.questionIndex<this.questions.length-1)this.questionIndex++;else this.generate()},
    generate(){this.cancelTimer();const version=++this.generationVersion;this.phase='thinking';this.generationTimer=setTimeout(()=>{if(version!==this.generationVersion)return;this.generationTimer=null;this.phase=this.simulateFailure?'error':'complete'},1800)},
    cancelTimer(){this.generationVersion++;if(this.generationTimer){clearTimeout(this.generationTimer);this.generationTimer=null}},
    cancel(){this.cancelTimer();this.phase='collecting'},
    reset(){this.cancelTimer();this.phase='collecting';this.questionIndex=0;this.answers={goal:'',time:'',experience:''}}
  }
}
</script>
<style>
.ai-ball-showcase{padding:24px;border-radius:24px;border:1px solid var(--sf-content-edge);background:var(--sf-ambient);color:var(--sf-text);font-family:var(--sf-font-family)}.ai-ball-showcase>header h2{font-size:24px;margin:0 0 8px}.ai-ball-showcase>header p{font-size:14px;line-height:1.7;color:var(--sf-text-secondary);margin:0}.ai-showcase-controls{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin:20px 0}.ai-showcase-controls select,.ai-showcase-controls>button{min-height:44px;border:1px solid var(--sf-glass-edge);background:var(--sf-glass);box-shadow:var(--sf-glass-shadow);border-radius:18px;padding:8px 14px;color:var(--sf-text);font:inherit}.ai-ball-stage{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:280px;text-align:center}.ai-ball-stage p{font-size:14px;color:var(--sf-text-secondary);line-height:1.6}.ai-states-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:18px 0 28px}.ai-states-grid article{display:flex;gap:10px;align-items:center;background:var(--sf-content-surface);padding:14px;border:1px solid var(--sf-content-edge);border-radius:22px}.ai-states-grid h3{font-size:15px;margin:0 0 5px}.ai-states-grid p{font-size:12px;line-height:1.6;color:var(--sf-text-secondary);margin:0}.ai-scenes-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.ai-scene{padding:20px;border-radius:24px;background:var(--sf-content-surface);border:1px solid var(--sf-content-edge);min-width:0}.ai-scene>h3{font-size:18px;margin:0 0 8px}.ai-review-note{font-size:12px;color:var(--sf-text-secondary);line-height:1.7}.ai-question-heading{display:flex;align-items:center;gap:10px;margin:20px 0}.ai-question-heading h4{font-size:20px;line-height:1.35;margin:0}.ai-step{font-size:12px;color:var(--sf-text-secondary);margin:0 0 5px}.ai-question-options{border:0;padding:0;margin:0 0 20px}.ai-scene-copy{font-size:15px;line-height:1.6;color:var(--sf-text-secondary)}.ai-home-preview{position:relative;min-height:400px;max-width:375px;padding:16px;background:var(--sf-ambient);border-radius:24px;overflow:hidden}.ai-home-preview>.sf-header{margin-bottom:16px;background:transparent}.ai-home-preview>.sf-card{margin-bottom:16px}.ai-home-entry{position:absolute;right:10px;bottom:14px;width:64px;height:64px;border:0;background:transparent;padding:0;border-radius:50%;cursor:pointer}.ai-home-hint{font-size:12px;color:var(--sf-text-secondary);margin:30px 0 0;padding-right:64px}
@media(max-width:900px){.ai-states-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.ai-ball-showcase{padding:16px}.ai-states-grid,.ai-scenes-grid{grid-template-columns:1fr}.ai-question-heading h4{font-size:18px}}
.ai-reference-strip{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:0 0 24px}.ai-reference-strip>h3,.ai-reference-strip>p{grid-column:1/-1;margin:0}.ai-reference-strip>p{font-size:12px;color:var(--sf-text-secondary)}.ai-reference-strip article{padding:14px;border:1px solid var(--sf-content-edge);border-radius:20px;background:var(--sf-content-surface)}.ai-reference-strip h4{margin:0 0 8px;font-size:14px}.ai-reference-images{display:flex;justify-content:space-around;gap:12px}.ai-reference-images figure{margin:0;text-align:center}.ai-reference-images img{display:block;border-radius:10px}.ai-reference-images figcaption{font-size:11px;margin-top:6px;color:var(--sf-text-secondary)}@media(max-width:700px){.ai-reference-strip{grid-template-columns:1fr}}
</style>
